// Integrare de livrare. Nu închide constatări: cere rapoarte deja închise de auditori.
const fs=require('fs'),path=require('path');const root=path.resolve(__dirname,'..');
const read=p=>JSON.parse(fs.readFileSync(path.join(root,p),'utf8').replace(/^\uFEFF/,''));
const save=(p,v)=>{const f=path.join(root,p),tmp=f+'.tmp';fs.writeFileSync(tmp,typeof v==='string'?v:JSON.stringify(v,null,2)+'\n','utf8');fs.renameSync(tmp,f);};
const groups=[['apple','AUDIT_APPLE_R2.md','doctoral_apple_perception','doctoral_robotics',['AUD-APPLE','AUD-CV'],16],['robotics','AUDIT_ROBOTICA_R2.md','doctoral_robotics','doctoral_apple_perception',['AUD-ROB','AUD-NET'],12],['transversal','AUDIT_TRANSVERSAL_R2.md','manager','doctoral_robotics',['AUD-SCI','AUD-UX','AUD-MET','AUD-DATA','AUD-SEC'],24],['governance','AUDIT_GUVERNANTA_R2.md','manager','doctoral_apple_perception',['AUD-GOV'],10]];
const findings=[],reviews=[];for(const [name,report,author,auditor,domains,count]of groups){const ff='07_audit/'+name+'_findings.json';const f=read(ff);if(f.some(x=>x.status!=='closed'))throw Error('Open findings '+name);findings.push(...f.map(x=>({...x,source_register:ff})));for(const domain of domains)reviews.push({domain,status:'accepted',report:'07_audit/'+report,findings_ref:ff,author_agent:author,auditor_agent:auditor,criteria_in_group:count});}
const audit={schema_version:'1.1',updated_at:new Date().toISOString(),status:'accepted',scope:'Documentație și comportamentele instrumentelor verificate izolat; implementare și teste fizice neexecutate',required_domains:reviews.map(r=>r.domain),reviews,findings,criteria_passed:62,criteria_total:62,findings_closed:findings.length};save('07_audit/REGISTRU.json',audit);
const tasks=read('03_plan/tasks.json');const refs={'DOC-01':'AUDIT_TRANSVERSAL_R2.md','DOC-02':'AUDIT_APPLE_R2.md','DOC-03':'AUDIT_ROBOTICA_R2.md','DOC-04':'AUDIT_TRANSVERSAL_R2.md','DOC-05':'AUDIT_GUVERNANTA_R2.md','DOC-06':'AUDIT_TRANSVERSAL_R2.md','DOC-07':'AUDIT_GUVERNANTA_R2.md'};
for(const t of tasks.tasks){if(refs[t.id]){t.status='accepted';t.accepted_at=new Date().toISOString();t.audit_ref='07_audit/'+refs[t.id];t.acceptance_evidence=[t.audit_ref,...t.outputs];t.next_action='Păstrează artefactele și redeschide auditul la modificări relevante';}}
if(process.argv.includes('--delivery-verified')){const proof=read('LIVRARE_CONFIRMATA.json');if(proof.status!=='verified'||proof.mismatches?.length)throw Error('Delivery not verified');const t=tasks.tasks.find(t=>t.id==='DOC-08');t.status='accepted';t.accepted_at=new Date().toISOString();t.audit_ref='07_audit/AUDIT_GUVERNANTA_R2.md';t.acceptance_evidence=['07_audit/VERIFICARE_AUTOMATA.json','LIVRARE_CONFIRMATA.json'];t.next_action='W00 inventar hardware și probe; copia finală trebuie reverificată după manifest nou';}
save('03_plan/tasks.json',tasks);
save('00_control/STATUS.json',{schema_version:'1.1',updated_at:new Date().toISOString(),stage:'documentation_accepted',documentary_audit:{criteria_passed:62,total:62,findings_closed:13,findings_open:0},implementation_status:'not_started',physical_tests:'not_run',current_task:tasks.tasks.find(t=>t.id==='DOC-08').status==='accepted'?'W00':'DOC-08',next_action:tasks.tasks.find(t=>t.id==='DOC-08').status==='accepted'?'Inventariază Mac/Xcode/iPhone și robotul; fixează profilurile apoi execută EX-01':'Generează livrabilele, verifică și copiază în Aplicație',checkpoint:'Capitole și registre auditate; ultimele rezultate fizice inexistente',delivery_proof:'LIVRARE_CONFIRMATA.json',canonical_target:'\\\\192.168.100.151\\site-uri\\3dscan.eva-org.com\\Aplicație\\Cercetare_si_arhitectura_robotica_2026-10-02',pending:['W00–W17 implementare și calificare','Hardware exact și calibrări','Build iOS/ROS și teste pe dispozitive','Studiu utilizatori și validări metrologice'],resume:'00_control/RELUARE.md'});
save('07_audit/AUDIT_FINAL_INTEGRAT.md','# Sinteza finală a auditurilor independente\n\nManagerul integrează verdictele, fără a înlocui auditorii sau a reinterpreta teste fizice neexecutate.\n\n| Domeniu | Autor | Auditor independent | Criterii | Constatări închise | Verdict |\n|---|---|---|---|---|---|\n| Apple percepție concurență | doctoral_apple_perception | doctoral_robotics | 16/16 | 2 | Acceptat documentar |\n| Robotică și transport | doctoral_robotics | doctoral_apple_perception | 12/12 | 4 | Acceptat documentar |\n| Produs metrologie metodologie date și securitate | manager | doctoral_robotics | 24/24 | 3 | Acceptat documentar |\n| Guvernanță reluare și instrumente | manager | doctoral_apple_perception | 10/10 | 4 | Acceptat documentar și comportamente testate |\n\nTotal:62/62criterii,13constatări remediate,0deschise în domeniile auditate. Rapoartele R1 și R2, remedierea și fixture-urile negative sunt păstrate. Există28roluri,26sarcini,42cerințe,19experimente umbrelă și41subteste, toate testele de produs fiind planificate. Bibliografia are40înregistrări și39URL-uri distincte, inclusiv o sursă juridică oficială cu acces limitat declarat.\n\nInstrumentele au fost testate prin8invocări R1 și21invocări R2, cu controale corectate și rezultate brute păstrate; acestea sunt teste ale gestiunii documentelor, nu ale aplicației iOS. HTML a fost inspectat vizual la1440px; PDF a fost generat automat. Această verificare vizuală nu reprezintă inspecția fiecărei pagini PDF.\n\nIntegritatea ultimei copii se verifică în MANIFEST_SHA256.json și LIVRARE_CONFIRMATA.json. Actualizarea livrabilelor după audit nu modifică verdictele asupra surselor auditate; schimbările de fond redeschid auditul. Testele fizice, compilarea Swift/ROS, expansiunea Xacro, verificarea juridică și validarea operațională rămân neexecutate.\n');
console.log(JSON.stringify({audit:'accepted',criteria:62,closed:findings.length,doc08:tasks.tasks.find(t=>t.id==='DOC-08').status}));
